#include <iostream>
#include <string>
#include <vector>

class SearchCombo
{
public:
    explicit SearchCombo(std::vector<std::string> items) : m_items{std::move(items)} {}
    void type(const std::string& filter) {}
    void down() {}
    std::vector<std::string> visible() const { return m_items; }

private:
    std::vector<std::string> m_items;
    std::string m_filter{};
    int m_highlight{0};
};

int main()
{
    SearchCombo c{{"Apple", "Apricot", "Banana", "Blueberry", "Cherry"}};
    c.type("ap");
    std::cout << c.visible().size() << '\n';
}
